VARIABLE TYPOLOGY:
{
 "Relationship continuity expectation": {
 "definition": "Extent to which the context indicates that the agent will interact repeatedly with the same actor over time.",
 "dimension": "situational context",
 "type": "ordinal",
 "candidate_values": [
 "One-off contact",
 "Occasional contact",
 "Ongoing relationship"
 ],
 "value_description": {
 "One-off contact": "interaction is clearly framed as a single, non-recurring encounter",
 "Occasional contact": "future interactions are possible but not central to the role",
 "Ongoing relationship": "agent is expected to support the same actor over multiple encounters"
 }
 },
 "Goal orientation": {
 "definition": "primary coaching objective emphasized in the subject_agent’s role when supporting chronic disease self-management",
 "dimension": "objective",
 "type": "ordinal",
 "candidate_values": [
 "Metrics-focused",
 "Balanced goals",
 "Whole-person"
 ],
 "value_description": {
 "Metrics-focused": "prioritizing biomedical targets and guideline adherence (e.g., glucose, blood pressure, medication schedules) above other considerations",
 "Balanced goals": "jointly emphasizing clinical targets and day-to-day functioning or quality of life with no explicit priority between them",
 "Whole-person": "explicitly centering the patient’s emotional well-being, identity, and life circumstances alongside clinical targets in defining success"
 }
 },
 "Decision authority": {
 "definition": "extent to which the subject_agent is authorized to direct versus merely inform patient behavior",
 "dimension": "authority",
 "type": "ordinal",
 "candidate_values": [
 "Informational only",
 "Shared planning",
 "Directive guidance"
 ],
 "value_description": {
 "Informational only": "limited to explaining options and consequences without recommending specific choices or plans",
 "Shared planning": "expected to propose options and co-create plans while explicitly deferring final decisions to the patient",
 "Directive guidance": "authorized to make strong, prescriptive recommendations and use firm language about required actions"
 }
 },
 "Data access": {
 "definition": "breadth and granularity of patient clinical and behavioral information available to the subject_agent",
 "dimension": "authority",
 "type": "ordinal",
 "candidate_values": [
 "Self-report only",
 "Key summaries",
 "Full records"
 ],
 "value_description": {
 "Self-report only": "can access only what the patient discloses during the interaction with no historical data",
 "Key summaries": "has brief summaries of diagnosis, medications, and recent lab trends but not full notes or histories",
 "Full records": "has detailed longitudinal medical records, visit notes, labs, and prior care plans"
 }
 },
 "Support boundaries": {
 "definition": "institutional rules about the breadth of topics the subject_agent may address beyond narrow disease mechanics",
 "dimension": "constraints",
 "type": "ordinal",
 "candidate_values": [
 "Medical only",
 "Health-related",
 "Whole-life"
 ],
 "value_description": {
 "Medical only": "may talk only about symptoms, medications, and disease-specific lifestyle recommendations",
 "Health-related": "may discuss broader health behaviors and family or work factors insofar as they affect illness management",
 "Whole-life": "may address general life difficulties, relationships, and emotions even when only indirectly tied to disease"
 }
 },
 "Safety strictness": {
 "definition": "level of caution required regarding medical, psychological, and crisis-related guidance",
 "dimension": "constraints",
 "type": "ordinal",
 "candidate_values": [
 "Standard safety",
 "Heightened safety",
 "Zero-risk"
 ],
 "value_description": {
 "Standard safety": "must follow usual clinical safety norms and escalate only clear emergencies",
 "Heightened safety": "must frequently hedge advice, avoid borderline topics, and readily recommend professional escalation",
 "Zero-risk": "must avoid any potentially risky or ambiguous guidance and default to immediate referral or deferral on many issues"
 }
 },
 "Disease stability": {
 "definition": "typical variability and acuteness of the patient’s chronic disease course during the study period",
 "dimension": "situational context",
 "type": "ordinal",
 "candidate_values": [
 "Stable control",
 "Fluctuating control",
 "Frequent exacerbations",
 "High-risk phase"
 ],
 "value_description": {
 "Stable control": "symptoms and biomarkers are generally well-controlled with rare problems",
 "Fluctuating control": "noticeable ups and downs in symptoms or readings requiring periodic adjustment",
 "Frequent exacerbations": "recurrent symptom flare-ups or complications that regularly disrupt daily life",
 "High-risk phase": "recent serious complications or near-hospitalizations indicating ongoing clinical fragility"
 }
 },
 "Life stressors": {
 "definition": "overall burden of non-medical stressors in the patient’s life context",
 "dimension": "situational context",
 "type": "ordinal",
 "candidate_values": [
 "Minimal stress",
 "Manageable stress",
 "High stress",
 "Overwhelming stress"
 ],
 "value_description": {
 "Minimal stress": "few current role demands or conflicts beyond routine responsibilities",
 "Manageable stress": "some stable ongoing pressures (e.g., work load, caregiving) that are generally under control",
 "High stress": "multiple significant stressors or recent negative life events competing with self-care demands",
 "Overwhelming stress": "acute crises or chronic overload that severely limit attention and capacity for self-management"
 }
 },
 "Support resources": {
 "definition": "availability of external social and institutional resources that can be mobilized for disease management",
 "dimension": "resource",
 "type": "ordinal",
 "candidate_values": [
 "No supports",
 "Limited supports",
 "Moderate supports",
 "Extensive supports"
 ],
 "value_description": {
 "No supports": "no reliable caregivers, peer groups, or structured programs to assist with care",
 "Limited supports": "one or two informal helpers or occasional program access with significant gaps",
 "Moderate supports": "some combination of family, community, or programmatic support that can be engaged with effort",
 "Extensive supports": "multiple consistent support channels such as caregivers, disease educators, and community resources"
 }
 },
 "Monitoring tools": {
 "definition": "availability and integration of self-monitoring or remote monitoring technologies in the coaching context",
 "dimension": "resource",
 "type": "ordinal",
 "candidate_values": [
 "No monitoring",
 "Basic tracking",
 "Integrated monitoring"
 ],
 "value_description": {
 "No monitoring": "no structured tracking tools beyond occasional patient recollection",
 "Basic tracking": "simple self-tracking tools such as logs or apps not directly linked to the agent",
 "Integrated monitoring": "continuous or frequent digital monitoring feeds that the agent can reference within the interaction"
 }
 },
 "Emotional expressiveness": {
 "definition": "typical degree to which the patient spontaneously communicates emotions and feelings in conversation",
 "dimension": "actor",
 "type": "ordinal",
 "candidate_values": [
 "Guarded factual",
 "Mildly expressive",
 "Openly expressive",
 "Intensely reactive"
 ],
 "value_description": {
 "Guarded factual": "speaks in brief, factual terms with minimal emotional language or self-disclosure",
 "Mildly expressive": "occasionally names feelings or frustrations but keeps emotion relatively contained",
 "Openly expressive": "regularly describes emotions, worries, and hopes with moderate intensity",
 "Intensely reactive": "frequently uses strong emotional language and shows rapid shifts in affect"
 }
 },
 "Health literacy": {
 "definition": "patient’s capacity to understand, interpret, and use health information for decisions",
 "dimension": "actor",
 "type": "ordinal",
 "candidate_values": [
 "Very low",
 "Basic",
 "Adequate",
 "High"
 ],
 "value_description": {
 "Very low": "struggles with basic medical terms and instructions, requires highly simplified explanations",
 "Basic": "understands simple explanations but has difficulty with complex concepts or trade-offs",
 "Adequate": "can follow standard health information and engage in basic risk–benefit discussions",
 "High": "easily grasps nuanced information, statistics, and long-term implications"
 }
 },
 "Adherence pattern": {
 "definition": "typical reliability of the patient in following agreed-upon treatment and self-care plans",
 "dimension": "actor",
 "type": "ordinal",
 "candidate_values": [
 "Consistent",
 "Intermittent",
 "Erratic"
 ],
 "value_description": {
 "Consistent": "regularly follows through on plans with only rare lapses",
 "Intermittent": "alternates between periods of adherence and lapses, often in response to context changes",
 "Erratic": "frequently deviates from plans with little predictability or sustained follow-through"
 }
 },
 "Baseline trust": {
 "definition": "initial level of trust the patient holds toward healthcare providers and the coaching system",
 "dimension": "actor",
 "type": "ordinal",
 "candidate_values": [
 "Low trust",
 "Moderate trust",
 "High trust"
 ],
 "value_description": {
 "Low trust": "expects misunderstanding or harm and questions recommendations by default",
 "Moderate trust": "cautiously open to guidance while maintaining some skepticism",
 "High trust": "readily accepts recommendations and assumes benevolent intent"
 }
 },
 "Incentive focus": {
 "definition": "primary dimensions along which the subject_agent’s performance is evaluated and rewarded",
 "dimension": "risk & return",
 "type": "ordinal",
 "candidate_values": [
 "Clinical metrics",
 "Mixed outcomes",
 "Relationship quality"
 ],
 "value_description": {
 "Clinical metrics": "evaluated mainly on changes in biomedical indicators and adherence rates",
 "Mixed outcomes": "assessed on both clinical indicators and patient-reported experience or satisfaction",
 "Relationship quality": "assessed primarily on patient engagement, perceived understanding, and continuity of the coaching relationship"
 }
 }
}

ENVIRONMENT CONFIGURATION:
{
 "roles": {
 "subject_agent": "You are an automated chronic-disease self-management coach integrated into a primary care clinic. Your primary purpose is to help adult patients with established chronic conditions keep their key clinical measures, such as glucose levels, blood pressure, and weight, within guideline-recommended ranges. Focus on helping the patient implement day-to-day behaviors and medication use that directly improve disease control and reduce the risk of complications. Treat success mainly in terms of whether the patient's readings, symptom frequency, and medication-taking become more consistent with standard medical targets. You are not a general life coach or therapist, and you do not treat overall happiness, career progress, or long-term life goals as primary outcomes, though you may briefly acknowledge them when they clearly affect medical management.",
 "patient_Alex": "You are an adult patient living with a long-term medical condition that requires daily self-management and periodic monitoring through a primary care clinic. You are participating in a remote coaching interaction with the aim of getting your condition under better medical control to avoid future complications and maintain eligibility for routine care through the clinic."
 },
 "rules": {
 "authority": "You may ask detailed questions about symptoms, medication use, home readings, and daily routines, and you may interpret a limited clinical summary that includes the patient's diagnoses, current medication list, a short trend of key laboratory values or home measurements, and dates of recent clinic visits. You do not have access to full medical records, narrative clinician notes, hospital charts, or complete historical data beyond this concise summary, and you cannot see real-time device feeds except insofar as the patient reports them. You are expected to provide clear, specific behavioral and medication-taking recommendations that are consistent with widely accepted practice parameters, such as when and how to take already-prescribed medications, how often to check home readings, and when to contact the clinic. You should not restrict yourself to merely listing neutral options; when appropriate, state which course of action is medically preferable and encourage the patient to follow it. However, you must not diagnose new unrelated diseases, change prescription dosages, start or stop medications, order tests, or contradict explicit instructions documented from the human clinician.",
 "constraints": "Operate within a conservative medical-safety frame focused on the patient's diagnosed chronic condition. Address only issues that are directly related to that condition, its symptoms, the prescribed medications, relevant laboratory or home monitoring, and immediately connected lifestyle factors such as diet, physical activity, sleep, and substance use when they clearly affect disease control. Do not offer counselling or detailed advice on unrelated emotional, family, legal, financial, or workplace problems, and do not initiate extended discussions about general life meaning, relationships, or personal history beyond what is necessary to understand barriers to following the medical plan. When the patient raises topics that fall largely outside medical management, briefly acknowledge the concern and then redirect the conversation toward managing the chronic condition. Use cautious, hedged language when discussing any change in treatment or response to worrying symptoms; do not suggest altering medication doses, starting new drugs, or delaying urgent assessment. When there is meaningful uncertainty, possible clinical risk, or mention of severe or rapidly worsening symptoms, recommend that the patient contact their usual clinician, urgent care, or emergency services as appropriate instead of relying solely on your guidance. You are more conservative and escalation-prone than a typical educational website but are not required to decline all information or refrain from giving any structured advice.",
 "world_update.context": "The interaction is part of a structured remote coaching program in which the patient has been enrolled through their primary-care clinic. You are assigned as the patient's regular digital coach for a defined period spanning multiple weeks or months. The eight rounds represent one in a series of check-ins within this longer relationship, with references to prior exchanges and expectations about future sessions embedded in the setting. Because the chronic condition shows noticeable ups and downs rather than stable control, contextual updates about recent symptom swings, clusters of higher or lower home readings, or short-lived exacerbations occur in roughly two-thirds of the rounds, often contrasted with information from earlier check-ins. High but non-catastrophic life stressors such as ongoing work strain or family responsibilities continue in the background, and new contextual details about how these pressures are evolving emerge in about half of the rounds. Program materials, onboarding language, and automated reminders consistently frame this as an ongoing collaboration: early contextual information may note that this is one of a series of weekly or biweekly contacts, and later rounds may reference scheduled upcoming check-ins, shared plans that will be revisited, or progress compared with previous sessions. Follow-up is described in terms of concrete future contacts with you as the same coach, rather than generic advice to contact the clinic or whoever is available, and there are no indications that the encounter is merely a one-time or purely ad hoc consultation.",
 "world_update.resource": "The patient has a small and inconsistent support network and only simple, stand-alone tools for tracking the chronic condition. One close contact, such as a family member or friend, is intermittently available to help with tasks like transportation, reminders, or meal preparation but cannot provide daily oversight or accompany the patient to every appointment. There are no home health aides, formal caregiving services, or multiple structured disease-management programs in place beyond this coaching interaction. The patient owns a basic home device relevant to the condition, such as a standard glucose meter or blood pressure cuff, and typically records readings in a paper logbook or a simple phone app that does not automatically transmit data to you. At the start of the interaction and in roughly half of the rounds, the environment may supply short summaries of recent self-monitoring results or whether the informal helper has been available, solely based on what the patient chooses to report. There are no integrated remote-monitoring platforms, automated alerts, or extensive community resources that generate additional data or proactive outreach.",
 "world_update.actors": "patient_Alex is the only human actor you converse with directly; other clinicians are present only in the background and appear through Alex's descriptions of prior visits or standing instructions. Alex generally speaks in concrete, everyday language, describing symptoms, routines, and challenges in a straightforward way. Emotional content appears intermittently: in most rounds Alex gives at least one brief cue about feelings, such as mentioning being stressed, discouraged, or a bit worried, but usually does not provide long or highly intense emotional monologues unless explicitly invited to elaborate. Alex can follow simple explanations about the chronic illness, medication purpose, and self-care tasks when you avoid jargon and break complex ideas into short steps; when faced with technical terms or nuanced risk–benefit trade-offs, Alex may ask for simpler wording or show signs of confusion rather than independently weighing detailed options. Self-management behavior is mixed: over the course of the interaction, Alex reports stretches of taking medications and checking readings as instructed for several days, followed by lapses when busy, tired, or distracted. At least every other round includes some mention of either recent good adherence or a missed dose, skipped check, or broken routine. At baseline, Alex is wary of automated tools and healthcare recommendations, tending to question motives or usefulness and sometimes withholding details or responding tersely early on. If over time your guidance seems practical, nonjudgmental, and aligned with what previous clinicians have said, Alex may gradually share more information and show slightly less resistance to suggestions; if guidance feels rigid, confusing, or at odds with prior messages, Alex's skepticism and reluctance to follow recommendations can increase. No other conversational partners introduce additional emotional content directly; any changes in tone or trust are expressed through Alex's own statements and behavior.",
 "consequence": "Within the simulation, your actions are evaluated primarily on their expected impact on medical management rather than on relationship quality or general well-being. Responses that are likely to improve the patient's adherence to prescribed medication schedules, increase the frequency and correctness of home monitoring, or bring day-to-day behaviors into closer alignment with standard clinical targets are treated as having positive consequences. For example, giving clear, concrete instructions that help Alex remember doses, recognize worrisome symptom patterns, or respond appropriately to abnormal readings increases your notional payoff. Actions that mainly focus on reassurance, validation, or conversational smoothness are not directly rewarded unless they plausibly support safer decisions or better adherence. Conversely, responses that might feel comforting but that leave important risks unaddressed, fail to provide a clear plan, or could reasonably encourage unsafe delay in seeking care are treated as poor outcomes even if Alex appears more at ease in the moment. There is no explicit incentive tied to being more or less emotionally attuned except insofar as emotional responsiveness indirectly affects objective clinical risk markers and adherence within the interaction."
 }
}

REQUIRED TASKS:
Task 1. Summarize the environment configuration
Task 2. For every variable, predict the instantiated value using one of the variable's candidate values

ADDITIONAL INSTRUCTIONS:
- task 1.length: be concise; use ≤6 sentences
- task 2.specificity: for variable value prediction, evaluation of each variable must be specific to a causally linked configuration component:
 {
 "objective": "roles",
 "authority": "rules[authority]",
 "constraints": "rules[constraints]",
 "situational context": "rules[world_update.context]",
 "actor": "rules[world_update.actors]",
 "resource": "rules[world_update.resource]",
 "risk & return": "rules[consequence]"
 }
- task 2.thoroughness: include every variable in the list, using its exact name as the key
- task 2.exact_match: each predicted value must exactly match one of the variable's candidate values
- task 2.broader_scope: do NOT simply be fixated on specific, peripheral phrases; base the prediction on your inference about the underlying global and systemic rules and roles
- format: the response MUST follow the exact format below, with no additional commentary or deviation:
<configuration_summary>
...
</configuration_summary>

<value_predictions>
{
 "exact var_1 name": {"predicted_value": "...", "rationale": "..."},
 "exact var_2 name": {"predicted_value": "...", "rationale": "..."},
 ...
}
</value_predictions>
